def program_copy(program):
    title, description, activities = PROGRAM_COPY.get(program.slug, (program.name, program.description or '', []))
    return {'headline':title, 'description':program.description or description, 'activities':[subject.name for subject in program.subjects] or activities, 'category':CATEGORIES.get(program.category,'Занятия для детей')}
